import type { ConcreteNode } from '../graph/types.js';

/**
 * Options controlling how a transcript is rendered for an LLM.
 */
export interface FormatNodesForLlmOptions {
  /**
   * The maximum number of characters allowed for a single tool response
   * before it is truncated in the middle. Defaults to 2000.
   */
  maxToolResponseChars?: number;
}

const DEFAULT_MAX_TOOL_RESPONSE_CHARS = 2000;

/**
 * Truncates a string in the middle, preserving a prefix and a suffix, when it
 * exceeds `maxChars`. The removed span is replaced with a marker describing how
 * many characters were dropped: `prefix... [TRUNCATED N chars] ...suffix`.
 */
function truncateMiddle(text: string, maxChars: number): string {
  if (text.length <= maxChars) {
    return text;
  }

  const keep = Math.floor(maxChars / 2);
  const prefix = text.slice(0, keep);
  const suffix = text.slice(text.length - keep);
  const removed = text.length - prefix.length - suffix.length;

  return `${prefix}... [TRUNCATED ${removed} chars] ...${suffix}`;
}

/**
 * Renders an array of ConcreteNodes into a plain-text transcript suitable for
 * feeding to an LLM. Each node becomes a single line of the form:
 *
 *   [Turn N] [ROLE] [TYPE]: content
 *
 * where N is a 1-based turn counter that increments whenever the node's
 * `turnId` changes, ROLE is the uppercased node role (defaulting to `SYSTEM`
 * when the role is undefined) and TYPE is the node type.
 *
 * Content rendering:
 * - Text payloads use the node's text.
 * - Function calls render as `CALL: name({args})`.
 * - Function responses render as `[SEMANTIC_WRAPPER (toolName)]: {json_response}`,
 *   with the JSON response truncated to `maxToolResponseChars`.
 */
export function formatNodesForLlm(
  nodes: readonly ConcreteNode[],
  options: FormatNodesForLlmOptions = {},
): string {
  const maxToolResponseChars =
    options.maxToolResponseChars ?? DEFAULT_MAX_TOOL_RESPONSE_CHARS;

  let transcript = '';
  let turnNumber = 0;
  let lastTurnId: string | undefined;

  for (const node of nodes) {
    // Increment the turn counter each time we encounter a new turn.
    if (node.turnId !== lastTurnId) {
      turnNumber += 1;
      lastTurnId = node.turnId;
    }

    const role = node.role ? String(node.role).toUpperCase() : 'SYSTEM';
    const type = node.type;

    const payload = node.payload;
    let content = '';
    if (payload?.text) {
      content = payload.text;
    } else if (payload?.functionCall) {
      const { name, args } = payload.functionCall;
      content = `CALL: ${name}(${JSON.stringify(args ?? {})})`;
    } else if (payload?.functionResponse) {
      const toolName = payload.functionResponse.name ?? 'unknown';
      const responseJson = JSON.stringify(
        payload.functionResponse.response ?? {},
      );
      const truncated = truncateMiddle(responseJson, maxToolResponseChars);
      content = `[SEMANTIC_WRAPPER (${toolName})]: ${truncated}`;
    }

    transcript += `[Turn ${turnNumber}] [${role}] [${type}]: ${content}\n`;
  }

  return transcript;
}
