 * @license
 * Copyright 2026 Google LLC
 * SPDX-License-Identifier: Apache-2.0
 */
import { type ConcreteNode, NodeType } from '../graph/types.js';
import type { ContextEnvironment } from '../pipeline/environment.js';
import { LlmRole } from '../../telemetry/llmRole.js';
import { debugLogger } from '../../utils/debugLogger.js';
import { formatNodesForLlm } from './formatNodesForLlm.js';

/**
 * The structured, machine-readable memory snapshot.
 *
 * Rather than a free-form text summary, the snapshot maintains separate,
 * incrementally-updatable lists so that each category of context can be merged,
 * pruned, and budgeted independently.
 */
export interface SnapshotState {
  /** Outstanding work items / goals the assistant is currently pursuing. */
  active_tasks: string[];
  /** Durable factual knowledge learned during the conversation. */
  discovered_facts: string[];
  /** User-imposed constraints, requirements and stylistic preferences. */
  constraints_and_preferences: string[];
  /** A rolling summary of the most recent turns/events. */
  recent_arc: string[];
}

/**
 * Information about the most recent snapshot node found within a set of nodes.
 */
export interface BaselineSnapshotInfo {
  /** The snapshot node itself. */
  node: ConcreteNode;
  /** The index of the node within the scanned array. */
  index: number;
  /** The (non-empty) snapshot text. */
  text: string;
}

/**
 * A patch to a single list within the SnapshotState. The LLM returns additions
 * to append and deletions to remove for each category.
 */
interface ListPatch {
  add?: string[];
  remove?: string[];
}

/**
 * The shape of the patch the LLM is asked to produce. Every field is optional;
 * missing fields leave the corresponding list untouched.
 */
interface SnapshotPatch {
  active_tasks?: ListPatch;
  discovered_facts?: ListPatch;
  constraints_and_preferences?: ListPatch;
  recent_arc?: ListPatch;
}

const DEFAULT_MAX_SUMMARY_TURNS = 5;
const DEFAULT_MAX_STATE_TOKENS = 4000;

/**
 * The order in which list items are dropped when the snapshot exceeds its token
 * budget. The lowest-priority (most disposable) category is listed first.
 */
const DROP_PRIORITY: Array<keyof SnapshotState> = [
  'recent_arc',
  'discovered_facts',
  'constraints_and_preferences',
  'active_tasks',
];

const SNAPSHOT_PATCH_SCHEMA: Record<string, unknown> = {
  type: 'OBJECT',
  properties: {
    active_tasks: {
      type: 'OBJECT',
      properties: {
        add: { type: 'ARRAY', items: { type: 'STRING' } },
        remove: { type: 'ARRAY', items: { type: 'STRING' } },
      },
    },
    discovered_facts: {
      type: 'OBJECT',
      properties: {
        add: { type: 'ARRAY', items: { type: 'STRING' } },
        remove: { type: 'ARRAY', items: { type: 'STRING' } },
      },
    },
    constraints_and_preferences: {
      type: 'OBJECT',
      properties: {
        add: { type: 'ARRAY', items: { type: 'STRING' } },
        remove: { type: 'ARRAY', items: { type: 'STRING' } },
      },
    },
    recent_arc: {
      type: 'OBJECT',
      properties: {
        add: { type: 'ARRAY', items: { type: 'STRING' } },
        remove: { type: 'ARRAY', items: { type: 'STRING' } },
      },
    },
  },
};

function createEmptyState(): SnapshotState {
  return {
    active_tasks: [],
    discovered_facts: [],
    constraints_and_preferences: [],
    recent_arc: [],
  };
}

/**
 * Coerce arbitrary parsed JSON into a well-formed SnapshotState, discarding any
 * unexpected shapes. Non-string entries are dropped.
 */
function coerceState(value: unknown): SnapshotState {
  const state = createEmptyState();
  if (!value || typeof value !== 'object') {
    return state;
  }
  const record = value as Record<string, unknown>;
  for (const key of Object.keys(state) as Array<keyof SnapshotState>) {
    const raw = record[key];
    if (Array.isArray(raw)) {
      state[key] = raw.filter(
        (item): item is string => typeof item === 'string',
      );
    }
  }
  return state;
}

/**
 * Applies a single list patch: removes deleted items, then appends new items
 * (de-duplicated against the existing list).
 */
function mergeList(existing: string[], patch?: ListPatch): string[] {
  let result = [...existing];

  if (patch?.remove && Array.isArray(patch.remove)) {
    const toRemove = new Set(patch.remove);
    result = result.filter((item) => !toRemove.has(item));
  }

  if (patch?.add && Array.isArray(patch.add)) {
    for (const item of patch.add) {
      if (typeof item === 'string' && !result.includes(item)) {
        result.push(item);
      }
    }
  }

  return result;
}

/**
 * Locates the most recent SNAPSHOT node with non-empty text within `targets`,
 * scanning from newest to oldest.
 */
export function findLatestSnapshotBaseline(
  targets: readonly ConcreteNode[],
): BaselineSnapshotInfo | undefined {
  for (let i = targets.length - 1; i >= 0; i--) {
    const node = targets[i];
    if (node.type === NodeType.SNAPSHOT) {
      const text = node.payload?.text;
      if (text && text.trim().length > 0) {
        return { node, index: i, text };
      }
    }
  }
  return undefined;
}

export class SnapshotGenerator {
  constructor(private readonly env: ContextEnvironment) {}

  /**
   * Synthesizes a structured snapshot from a raw transcript, incrementally
   * updating a previously-persisted state when one is provided.
   *
   * @param nodes The transcript nodes to fold into the snapshot.
   * @param previousStateJson A JSON-serialized {@link SnapshotState} to update.
   * @param options Tuning knobs for summary length and token budget.
   * @returns A JSON-serialized {@link SnapshotState}.
   */
  async synthesizeSnapshot(
    nodes: readonly ConcreteNode[],
    previousStateJson?: string,
    options?: { maxSummaryTurns?: number; maxStateTokens?: number },
  ): Promise<string> {
    const maxSummaryTurns =
      options?.maxSummaryTurns ?? DEFAULT_MAX_SUMMARY_TURNS;
    const maxStateTokens = options?.maxStateTokens ?? DEFAULT_MAX_STATE_TOKENS;

    // Establish the starting state.
    let previousState: SnapshotState;
    if (previousStateJson) {
      try {
        previousState = coerceState(JSON.parse(previousStateJson));
      } catch {
        // A malformed previous state is treated as empty rather than fatal.
        previousState = createEmptyState();
      }
    } else {
      previousState = createEmptyState();
    }

    // The "previous state unmodified" value returned on any failure.
    const fallback = previousStateJson ?? JSON.stringify(previousState);

    const transcript = formatNodesForLlm(nodes);

    const systemPrompt = `You are an expert Context Memory Manager. You maintain a structured, machine-readable memory snapshot of a conversation between a user and an AI assistant.

You will be given the CURRENT MASTER STATE (when it exists) and a raw transcript of new conversation turns. Produce a PATCH that incrementally updates the master state. The state has four lists:
- active_tasks: outstanding goals or work items the assistant is pursuing.
- discovered_facts: durable factual knowledge learned during the conversation.
